import json
C = json.load(open("out/consolidated.json")); H = json.load(open("out/honest_scores.json")); V0 = json.load(open("out/v40_scores.json"))
S = json.load(open("out/separability.json")); SH = json.load(open("out/shared_artefact.json"))
p = lambda x: "n/a" if x != x or x is None else f"{100*x:.1f}"
print("## Negative control: share of the unpainted print shown as paint (%)")
print("| Pipeline | clean capture | unruly A | unruly B |\n|---|---:|---:|---:|")
print(f"| v4.0/4.1.0 (VDZ-era), C*ab / LRC | {p(V0['unpainted clean raw']['unpainted_shown'])} / {p(V0['unpainted clean lrc']['unpainted_shown'])} | {p(V0['unpainted A raw']['unpainted_shown'])} / {p(V0['unpainted A lrc']['unpainted_shown'])} | not run |")
print(f"| v4.1.2 (current), C*ab / LRC | {p(C['v4.1.2 raw | unpainted | clean']['unpainted_shown'])} / {p(C['v4.1.2 lrc | unpainted | clean']['unpainted_shown'])} | {p(C['v4.1.2 raw | unpainted | A']['unpainted_shown'])} / {p(C['v4.1.2 lrc | unpainted | A']['unpainted_shown'])} | {p(C['v4.1.2 raw | unpainted | B']['unpainted_shown'])} / {p(C['v4.1.2 lrc | unpainted | B']['unpainted_shown'])} |")
print(f"| TODO.md prototype, good picks | {p(C['TODO good | unpainted | clean']['unpainted_shown'])} | {p(C['TODO good | unpainted | A']['unpainted_shown'])} | {p(C['TODO good | unpainted | B']['unpainted_shown'])} |")
print(f"| TODO.md prototype, automatic reference | {p(C['TODO auto | unpainted | clean']['unpainted_shown'])} | {p(C['TODO auto | unpainted | A']['unpainted_shown'])} | {p(C['TODO auto | unpainted | B']['unpainted_shown'])} |")
h = lambda k: H[k]["s25"]
print(f"| Alternative, one capture, good marks | {p(h('H5 unpainted print, clean, good marks')['unpainted_shown'])} | {p(h('H5 unpainted print, unruly A, good marks')['unpainted_shown'])} | {p(h('H5 unpainted print, unruly B, good marks')['unpainted_shown'])} |")
print(f"| Alternative, two captures A+B | | {p(h('P5 two captures of the unpainted print')['unpainted_shown'])} | |")
print(f"| Alternative, two captures A+C (same-sign lens fringing) | | {p(h('R unpainted A+C')['unpainted_shown'])} | |")
print(f"| Alternative, two captures B+C | | | {p(h('R unpainted B+C')['unpainted_shown'])} |")
print()
print("## Painted print: share of each region shown (%), unruly capture A unless stated")
keys = ("wash", "cheeks", "lips", "patch_yellow", "foxing", "mat_burn", "retouch_matched", "retouch_neutral")
print("| Pipeline | unpainted areas | " + " | ".join(keys) + " |\n|---|" + "---:|" * (len(keys) + 1))
def row(name, d): print(f"| {name} | {p(d['unpainted_shown'])} | " + " | ".join(p(d[k]) for k in keys) + " |")
row("v4.0/4.1.0 C*ab", V0["normal A raw"]); row("v4.0/4.1.0 LRC", V0["normal A lrc"])
row("v4.1.2 C*ab", C["v4.1.2 raw | normal | A"]); row("v4.1.2 LRC", C["v4.1.2 lrc | normal | A"])
row("TODO.md, good picks (clean capture)", C["TODO good | normal | clean"])
row("TODO.md, good picks", C["TODO good | normal | A"])
row("TODO.md, automatic", C["TODO auto | normal | A"])
row("TODO.md, automatic, wash over 80% (clean)", C["TODO auto | extensive | clean"])
row("TODO.md, automatic, wash over 80%", C["TODO auto | extensive | A"])
row("Alternative, one capture (clean)", h("H0 clean, good marks"))
row("Alternative, one capture", h("H1 unruly A, good marks"))
row("Alternative, one capture, mark on the wash", h("H2 unruly A, one mark on the faint wash"))
row("Alternative, A+B", h("P1 two captures (A+B), good marks"))
row("Alternative, A+B, A's mark on the wash", h("P2 two captures, A's marks contaminated"))
row("Alternative, A+C", h("R normal A+C")); row("Alternative, B+C", h("R normal B+C"))
print()
print("## Separability of paint from unpainted print by distance from the TODO reference (good picks)")
print("| capture | unpainted median / p90 (a*b*) | wash median, AUC | cheeks AUC | blue flag AUC |\n|---|---|---|---|---|")
for k, r in S.items():
    print(f"| {k} | {r['unpainted_median']:.1f} / {r['unpainted_p90']:.1f} | {r['wash_median']:.1f}, {r['wash_auc']:.3f} | {r['cheeks_auc']:.3f} | {r['flag_blue_auc']:.3f} |")
print()
for k, v in SH.items(): print(f"- {k}: {100*v['fp']:.2f}% of unpainted shown, {100*v['on_edges']:.0f}% of it on edges")
